"""
Instalador de la VERSIÓN 1.0.2 — Apariencia "sala de control" (NOC Syslog Inteligente).

Ejecútelo desde la carpeta principal del proyecto, con la v1.0.1 ya subida a GitHub:
    python instalar_v102.py

- Login con una red de equipos animada de fondo y dashboard con cuadrícula y brillos suaves.
- Solo cambios visuales (CSS y HTML).
- No cambia el funcionamiento: después ejecute  python -m backend.scripts.pruebas_v1
- SEGURIDAD: antes de tocar nada comprueba que cada archivo sea EXACTAMENTE el de la v1.0.1.
  Si alguno es distinto, se detiene sin cambiar ningún archivo.
"""
import base64
import hashlib
import json
import zlib
from pathlib import Path

ARCHIVOS = json.loads('{"CHANGELOG.md": {"antes": "04c95754e9677a369fcc3905860a0ede6873ea6216aa4fde32de09fe55c1958d", "despues": "2abbd98a865b25b304d9b5a03a10b52257f5568bc60fc18c5c48fed755b97a09", "contenido": ""}, "backend/app/config.py": {"antes": "5c0f74b1f52e28a71bce09c1155fef34809d72c8e0f7cf9a80dcb5f5ebee6722", "despues": "82f852ac4bef99bdac267a67704271f2c3cffca06a049c1b4d1207ce4f83c723", "contenido": ""}, "frontend/index.html": {"antes": "5c0670f5b19a615d422ae04ef0078ad353c0ac79efa95c0f0a43a11be2c9ecec", "despues": "671fe6fc7f35bb15b093b8da9912566a5fce5b2e0259e00075ac03d657ef7b1f", "contenido": ""}, "frontend/login.html": {"antes": "a0de7117cce6264cef1e3c81ce46d0e336aa906d8410d8faa32f502306c160c7", "despues": "6e04900d0a7655e5093096e92801184a4e710436781f3a7f358c386580440723", "contenido": ""}, "frontend/styles.css": {"antes": "390a26a18ecbf0ca5da74773c170e46fd87c0deccf7a84f8231e297d0f6dabf0", "despues": "6e65b3fe571ab83f3b3f8bd652a417c2d6b95515ea1f6c8bec06ee0d4e70f24f", "contenido": ""}}')


def huella(texto):
    """SHA-256 del texto con saltos de línea normalizados (Windows usa CRLF, Git guarda LF)."""
    return hashlib.sha256(texto.replace("\r\n", "\n").encode("utf-8")).hexdigest()


def main():
    """Revisa todos los archivos y, solo si todos coinciden con la v1.0.1, escribe la v1.0.2."""
    if not (Path("backend/app").is_dir() and Path("frontend").is_dir()):
        raise SystemExit("✖ Ejecútelo desde la carpeta principal del proyecto (donde están backend y frontend)")
    por_escribir, distintos, listos = [], [], 0
    for ruta, info in ARCHIVOS.items():
        p = Path(ruta)
        actual = huella(p.read_text(encoding="utf-8")) if p.exists() else None
        if actual == info["despues"]:
            listos += 1
        elif actual == info["antes"]:
            por_escribir.append((p, info))
        else:
            distintos.append(ruta)
    if distintos:
        print("✖ Estos archivos no son los de la v1.0.1 (¿cambios sin subir?). No se cambió nada:")
        for ruta in distintos:
            print("   -", ruta)
        raise SystemExit("Revise con 'git status' y 'git diff', o mande una captura.")
    for p, info in por_escribir:
        p.parent.mkdir(parents=True, exist_ok=True)
        texto = zlib.decompress(base64.b64decode(info["contenido"])).decode("utf-8")
        p.write_text(texto, encoding="utf-8", newline="\n")
        print(f"  ✔ {p.as_posix()}")
    print(f"\n{len(por_escribir)} archivos actualizados, {listos} ya estaban listos.")
    print("Listo: versión 1.0.2. Reinicie el NOC y presione Ctrl + Shift + R en el navegador.")


main()
